def find_solution(a, b, n):
    # Extended Euclidean Algorithm to find gcd and coefficients x, y such that ax + by = gcd(a,b)
    def extended_gcd(aa, bb):
        if bb == 0:
            return (aa, 1, 0)
        gcd, x1, y1 = extended_gcd(bb, aa % bb)
        x = y1
        y = x1 - (aa // bb) * y1
        return gcd, x, y

    gcd, x0, y0 = extended_gcd(a, b)
    if n % gcd != 0:
        return None  # No integer solutions exist

    # Scale the solution by n // gcd
    x = x0 * (n // gcd)
    y = y0 * (n // gcd)
    return (x, y)

