def get_total_number_of_sequences(n: int, max_element: int) -> int:
    # dp[i][x] = number of sequences of length i starting with x
    # We want sum of dp[n][x] for x in [1..max_element]
    # Recurrence: dp[i][x] = sum of dp[i-1][y] for y >= 2*x and y <= max_element

    if n == 1:
        return max_element  # sequences of length 1 can start with any from 1..max_element

    dp_prev = [0] * (max_element + 2)
    for x in range(1, max_element + 1):
        dp_prev[x] = 1  # sequences of length 1 starting with x

    for length in range(2, n + 1):
        dp_curr = [0] * (max_element + 2)
        # suffix sums for dp_prev to enable quick sum of dp_prev[y] for y >= 2*x
        suffix_sum = [0] * (max_element + 3)
        for i in range(max_element, 0, -1):
            suffix_sum[i] = suffix_sum[i + 1] + dp_prev[i]

        for x in range(1, max_element + 1):
            start = 2 * x
            if start > max_element:
                dp_curr[x] = 0
            else:
                dp_curr[x] = suffix_sum[start]

        dp_prev = dp_curr

    return sum(dp_prev[1:max_element + 1])

