def find_Max(arr, start, end):
    # Base case: if the segment contains only one element
    if start == end:
        return arr[start]
    # If the segment is already sorted (no rotation in this segment)
    if arr[start] < arr[end]:
        return arr[end]
    mid = (start + end) // 2
    # If mid element is greater than the next element, mid is max
    if mid < end and arr[mid] > arr[mid + 1]:
        return arr[mid]
    # If mid element is less than the previous element, previous element is max
    if mid > start and arr[mid] < arr[mid - 1]:
        return arr[mid - 1]
    # Decide which side to go
