def filter_data(data, thresholds):
    """
    Filters the measurements of people stored in a dictionary based on given thresholds.

    Parameters:
    - data: dict of {person: {measurement_name: value, ...}, ...}
    - thresholds: dict of {measurement_name: (min_value, max_value)}

    Returns:
    - dict with the same structure, but only measurements within the specified thresholds are kept.
      Measurements outside thresholds are removed from each person's dictionary.
      If a person ends up with no measurements after filtering, they remain in the dict with an empty dict.
    """
    filtered = {}
    for person, measurements in data.items():
        filtered_measurements = {}
        for measure, value in measurements.items():
            if measure in thresholds:
                min_val, max_val = thresholds[measure]
                if min_val <= value <= max_val:
                    filtered_measurements[measure] = value
            else:
                # If no threshold provided for this measurement, keep it by default
                filtered_measurements[measure] = value
        filtered[person] = filtered_measurements
    return filtered

