    # We want non-negative integers x,y such that a*x + b*y = n.
    # If no such solution exists, return None.

    # Handle trivial cases
    if n < 0:
        return None
    if a == 0 and b == 0:
        return (0, 0) if n == 0 else None
    if a == 0:
        if n % b == 0 and n // b >= 0:
            return (0, n // b)
        else:
