    # Since x,y >= 0, try all x from 0 up to n//a (integer division)
    # For each x, check if (n - a*x) is divisible by b and y = (n - a*x)/b >= 0

    max_x = n // a
    for x in range(max_x + 1):
        remainder = n - a * x
        if remainder < 0:
            break
        if remainder % b == 0:
            y = remainder // b
            if y >= 0:
                return (x, y)

    return None

