def find_solution(a, b, n):
    # We want integer solutions (x, y) to a*x + b*y = n,
    # and to return the first valid solution found as
    # ('x = ', x, ', y = ', y).

    # Handle special cases:
    if a == 0 and b == 0:
        if n == 0:
            return ('x = ', 0, ', y = ', 0)
        else:
            return None

    if a == 0:
        # b*y = n => y = n/b if integer
        if b != 0 and n % b == 0:
            return ('x = ', 0, ', y = ', n // b)
        else:
            return None

    if b == 0:
        # a*x = n => x = n/a if integer
        if a != 0 and n % a == 0:
            return ('x = ', n // a, ', y = ', 0)
        else:
            return None

    # General case:
    # We will try values of x from 0 up to abs(n) and from 0 down to -abs(n),
    # but starting from 0 to find the first solution with x >= 0,
    # then if none found, try x < 0.
    # This approach is consistent with the example that find_solution(1,1,5)
    # returns x=0, y=5 (not x=-5,y=10).

    limit = abs(n) if n != 0 else 1

    # Try non-negative x first
    for x in range(0, limit + 1):
        remainder = n - a * x
        if remainder % b == 0:
            y = remainder // b
            return ('x = ', x, ', y = ', y)

    # Then try negative x
    for x in range(-1, -limit - 1, -1):
        remainder = n - a * x
        if remainder % b == 0:
            y = remainder // b
            return ('x = ', x, ', y = ', y)

    return None

