def monotonic(l: list):
    if len(l) < 2:
        return True
    nondecreasing = all(x <= y for x, y in zip(l, l[1:]))
    nonincreasing = all(x >= y for x, y in zip(l, l[1:]))
    return nondecreasing or nonincreasing

def circular_shift(x, shift):
    s = str(x)
    n = len(s)
    if shift > n:
        return s[::-1]
    # Positive shift means circular shift to the right
    shift = shift % n  # Normalize shift
    if shift == 0:
        return s
    return s[-shift:] + s[:-shift]

def smallest_change(arr):
    n = len(arr)
    changes = 0
    for i in range(n // 2):
        if arr[i] != arr[n - 1 - i]:
            changes += 1
    return changes

def total_match(lst1, lst2):
    if not lst1 and not lst2:
        return lst1
    sum1 = sum(len(s) for s in lst1)
    sum2 = sum(len(s) for s in lst2)
    if sum1 >= sum2:
        return lst1
    else:
        return lst2

def prime_length(string):
    """Return True if the length of the string is a prime number, False otherwise."""
    n = len(string)
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return False
    return True

import re

def anti_shuffle(s):
    def sort_word(word):
        # Separate trailing non-alphabetic characters
        m = re.match(r'^([A-Za-z]+)([^A-Za-z]*)$', word)
        if m:
            core, tail = m.groups()
            sorted_core = ''.join(sorted(core))
            return sorted_core + tail
        else:
            # If no letters, just return the word as is
            return word

    # Use regex to split by words and spaces preserving all
    parts = re.findall(r'\S+|\s+', s)
    result = []
    for part in parts:
        if part.isspace():
            result.append(part)
        else:
            result.append(sort_word(part))
    return ''.join(result)

def count_upper(s):
    vowels = {'A', 'E', 'I', 'O', 'U'}
    return sum(1 for i in range(0, len(s), 2) if s[i] in vowels)

def move_one_ball(arr):
    if not arr:
        return True

    n = len(arr)
    for shift in range(n):
        # Right shift by `shift`: last `shift` elements come to front
        shifted = arr[-shift:] + arr[:-shift] if shift > 0 else arr
        if all(shifted[i] <= shifted[i+1] for i in range(n-1)):
            return True
    return False

def select_words(s, n):
    vowels = set('aeiouAEIOU')
    if not s:
        return []
    words = s.split()
    result = []
    for word in words:
        consonant_count = sum(1 for ch in word if ch.isalpha() and ch not in vowels)
        if consonant_count == n:
            result.append(word)
    return result

def maximum(arr, k):
    if k == 0:
        return []
    freq = {}
    for num in arr:
        freq[num] = freq.get(num, 0) + 1
    # Select numbers with frequency >= 2
    candidates = [num for num, count in freq.items() if count >= 2]
    # Sort descending
    candidates.sort(reverse=True)
    # Return up to k elements
    return candidates[:k]

def digits(n):
    odd_digits = [int(d) for d in str(n) if int(d) % 2 == 1]
    if not odd_digits:
        return 0
    product = 1
    for d in odd_digits:
        product *= d
    return product

